import React, { useState, useEffect } from "react";
import ChatSidebar from "../components/ChatSidebar";
import ChatMain from "../components/ChatMain";
import axios from "axios";
import "../styles/Chat.css";

const Chat = () => {
  const [selectedConversation, setSelectedConversation] = useState(null);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState("");
  const [user, setUser] = useState(null);

  // Load user from localStorage
  useEffect(() => {
    const storedUser = JSON.parse(localStorage.getItem("user"));
    setUser(storedUser);
  }, []);

  // Load messages when conversation changes
  useEffect(() => {
    const fetchMessages = async () => {
      try {
        if (!selectedConversation?._id) return;
        const res = await axios.get(`/api/messages/${selectedConversation._id}`);
        setMessages(res.data);
      } catch (err) {
        console.error("Error loading messages:", err);
      }
    };
    fetchMessages();
  }, [selectedConversation]);

  // Handle sending a message
  const handleSend = async () => {
    try {
      if (!newMessage.trim() || !selectedConversation) return;
      const res = await axios.post("/api/messages", {
        conversationId: selectedConversation._id,
        senderId: user._id,
        text: newMessage,
      });
      setMessages([...messages, { ...res.data, fromSelf: true }]);
      setNewMessage("");
    } catch (err) {
      console.error("Error sending message:", err);
    }
  };

  // Create conversation if it's just a selected user object
  const handleSelectConversation = async (conversationOrUser) => {
    // if conversationOrUser has _id, it's already a conversation
    if (conversationOrUser._id) {
      setSelectedConversation(conversationOrUser);
      return;
    }

    try {
      const res = await axios.post("/api/conversations", {
        senderId: user._id,
        receiverId: conversationOrUser._id,
        participantUsernames: [user.username, conversationOrUser.username],
      });
      setSelectedConversation(res.data);
    } catch (err) {
      console.error("Error creating conversation:", err);
    }
  };

  return (
    <div className="chat-container">
      <ChatSidebar
        onSelectConversation={handleSelectConversation}
        selectedConversation={selectedConversation}
      />
      <ChatMain
        selectedConversation={selectedConversation}
        messages={messages}
        newMessage={newMessage}
        setNewMessage={setNewMessage}
        handleSend={handleSend}
      />
    </div>
  );
};

export default Chat;
